mapper.select:
SELECT
    r.id, r.recharge_no, r.member_id, r.principal_amount, r.gift_amount,
    r.gift_source, r.gift_frozen, r.pay_method, r.remark, r.create_time,
    m.name AS member_name, m.phone AS member_phone,
    s.name AS store_name,
    a.name AS activity_name,
    u.nickname AS operator_name
FROM salon_recharge_order r
LEFT JOIN salon_member m ON m.id = r.member_id AND m.deleted = 0
LEFT JOIN salon_store s ON s.id = r.store_id AND s.deleted = 0
LEFT JOIN salon_recharge_activity a ON a.id = r.activity_id AND a.deleted = 0
LEFT JOIN sys_user u ON u.id = r.operator_id AND u.deleted = 0

    r.deleted = 0

        AND (
            r.recharge_no LIKE CONCAT('%', CAST(#{q.keywords} AS text), '%')
            OR m.name LIKE CONCAT('%', CAST(#{q.keywords} AS text), '%')
            OR m.phone LIKE CONCAT('%', CAST(#{q.keywords} AS text), '%')
        )


        AND r.member_id = #{q.memberId}


        AND r.pay_method = #{q.payMethod}


        AND r.gift_source = #{q.giftSource}


        AND r.tenant_id = #{q.tenantId}


        AND r.store_id = #{q.storeId}


        AND r.create_time >= #{q.startTime}


        AND r.create_time <= #{q.endTime}




                AND 1 = 0


                AND (


                            OR r.store_id IN

                                #{storeId}



                            OR r.create_by = #{q.permissionUserId}


                )




ORDER BY r.create_time DESC
